#!/usr/bin/env python3
"""json-tui reimplementation - JSON visualizer with an interactive terminal UI."""

import os
import sys
import json


HELP_TEXT = (
    "  json-tui {OPTIONS} [file]\n"
    "\n"
    "    A JSON terminal UI\n"
    "\n"
    "  OPTIONS:\n"
    "\n"
    "      file                              A JSON file. Omit to read from stdin.\n"
    "      -h, --help                        Display this help menu.\n"
    "      -v, --version                     Print version.\n"
    "      -k, --key, --keybinding           Display key binding.\n"
    "      -f, --fullscreen                  Display the JSON in fullscreen, in an\n"
    "                                        alternate buffer\n"
    "      \"--\" can be used to terminate flag options and force all following\n"
    "      arguments to be treated as positional options\n"
    "\n"
    "    If no file is given, json-tui reads JSON from the standard input\n"
    "    Please report bugs to:https://github.com/ArthurSonzogni/json-tui/issues\n"
)

VERSION_TEXT = "1.4.1\n"


def build_keybinding() -> bytes:
    """Build the exact byte sequence for --keybinding output."""
    # Each row has two cells: 11 chars wide + 16 chars wide
    W1, W2 = 11, 16
    NL = b"\r\n"
    top = "┌" + "─" * W1 + "┬" + "─" * W2 + "┐"
    sep = "├" + "─" * W1 + "┼" + "─" * W2 + "┤"
    bot = "└" + "─" * W1 + "┴" + "─" * W2 + "┘"

    def pad(text: str, w: int) -> str:
        # visible width of text measured in terminal cells; our strings are ASCII or
        # contain unicode arrows that are each 1 terminal cell
        return text + " " * (w - _wlen(text))

    def row(a: str, b: str) -> bytes:
        return ("│" + pad(a, W1) + "│" + pad(b, W2) + "│").encode("utf-8") + NL

    def colored_row(a: str, b: str) -> bytes:
        return (
            "│\x1b[36m\x1b[49m" + pad(a, W1) + "\x1b[39m\x1b[49m"
            "│\x1b[36m\x1b[49m" + pad(b, W2) + "\x1b[39m\x1b[49m│"
        ).encode("utf-8") + NL

    out = bytearray()
    out += top.encode("utf-8") + NL
    out += colored_row("keys", "action")
    out += sep.encode("utf-8") + NL
    out += row("Navigate", "← ↑ ↓ →")
    out += row("", "h j k l")
    out += row("", "Mouse::WheelUp")
    out += row("", "Mouse::WheelDown")
    out += sep.encode("utf-8") + NL
    out += row("Toggle", "enter")
    out += row("", "Mouse::Left")
    out += sep.encode("utf-8") + NL
    out += row("Deep", "")
    out += row(" - Expand", "+")
    out += row(" - Collapse", "-")
    out += sep.encode("utf-8") + NL
    out += row("Exit", "Escape")
    out += row("", "q")
    out += sep.encode("utf-8") + NL
    out += row("Navigate", "")
    out += row(" - first", "page-up")
    out += row(" - last", "page-down")
    out += row(" - top", "gg")
    out += row(" - bottom", "G")
    out += bot.encode("utf-8") + b"\x00\n"
    return bytes(out)


def _wlen(s: str) -> int:
    # Count "cells" - treat any non-combining char as 1 cell.
    return len(s)


# ----- argument parsing -----

def parse_args(argv):
    """Parse command-line args.

    Returns a dict with keys: help, version, keybinding, fullscreen, file (or None),
    error (string or None).
    """
    state = {
        "help": False,
        "version": False,
        "keybinding": False,
        "fullscreen": False,
        "file": None,
        "error": None,
    }
    positional = []
    after_dashdash = False
    i = 0
    while i < len(argv):
        a = argv[i]
        if after_dashdash:
            positional.append(a)
        elif a == "--":
            after_dashdash = True
        elif a.startswith("--"):
            name = a[2:]
            if name == "help":
                state["help"] = True
            elif name == "version":
                state["version"] = True
            elif name in ("key", "keybinding"):
                state["keybinding"] = True
            elif name == "fullscreen":
                state["fullscreen"] = True
            else:
                state["error"] = "Invalid arguments"
                return state
        elif a.startswith("-") and len(a) >= 2:
            # short options (possibly combined: -hf, -kv, etc.)
            for ch in a[1:]:
                if ch == "h":
                    state["help"] = True
                elif ch == "v":
                    state["version"] = True
                elif ch == "k":
                    state["keybinding"] = True
                elif ch == "f":
                    state["fullscreen"] = True
                else:
                    state["error"] = "Invalid arguments"
                    return state
        else:
            positional.append(a)
        i += 1
    if len(positional) > 1:
        state["error"] = "Invalid arguments"
        return state
    if positional:
        state["file"] = positional[0]
    return state


# ----- JSON parsing with error messages similar to nlohmann json -----

class JsonParseError(Exception):
    def __init__(self, line, column, message):
        self.line = line
        self.column = column
        self.message = message
        super().__init__(message)

    def __str__(self):
        return (
            f"[json.exception.parse_error.101] parse error at line "
            f"{self.line}, column {self.column}: {self.message}"
        )


class JsonParser:
    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.line = 1
        self.col = 1

    def eof(self):
        return self.pos >= len(self.text)

    def peek(self):
        return self.text[self.pos] if self.pos < len(self.text) else ""

    def advance(self):
        ch = self.text[self.pos]
        self.pos += 1
        if ch == "\n":
            self.line += 1
            self.col = 1
        else:
            self.col += 1
        return ch

    def skip_ws(self):
        while not self.eof() and self.peek() in " \t\n\r":
            self.advance()

    def error_empty(self):
        raise JsonParseError(
            self.line, self.col,
            "attempting to parse an empty input; "
            "check that your input string or stream contains the expected JSON",
        )

    def error_unexpected_value(self, last_read, context="value"):
        msg = (
            f"syntax error while parsing {context} - "
            f"unexpected end of input; expected '[', '{{', or a literal"
            if last_read == "<eof>"
            else
            f"syntax error while parsing {context} - "
            f"invalid literal; last read: '{last_read}'"
        )
        raise JsonParseError(self.line, self.col, msg)

    def parse(self):
        self.skip_ws()
        if self.eof():
            self.error_empty()
        val = self.parse_value()
        self.skip_ws()
        # trailing content ignored/error? nlohmann fails on extra content with 101
        if not self.eof():
            # unexpected content
            raise JsonParseError(
                self.line, self.col,
                f"syntax error while parsing value - unexpected '{self.peek()}'; "
                f"expected end of input",
            )
        return val

    def parse_value(self, context="value"):
        self.skip_ws()
        if self.eof():
            raise JsonParseError(
                self.line, self.col,
                f"syntax error while parsing {context} - "
                f"unexpected end of input; expected '[', '{{', or a literal",
            )
        ch = self.peek()
        if ch == '{':
            return self.parse_object()
        if ch == '[':
            return self.parse_array()
        if ch == '"':
            return self.parse_string()
        if ch == '-' or ch.isdigit():
            return self.parse_number()
        if ch in "tfn":
            return self.parse_keyword()
        # invalid
        last_read = self._read_literal_token()
        raise JsonParseError(
            self.line, self.col - len(last_read),
            f"syntax error while parsing {context} - "
            f"invalid literal; last read: '{last_read}'",
        )

    def _read_literal_token(self):
        start = self.pos
        while not self.eof() and self.peek() not in " \t\n\r,:{}[]\"":
            self.advance()
            if self.pos - start >= 8:
                break
        return self.text[start:self.pos] or self.peek()

    def parse_object(self):
        self.advance()  # consume '{'
        obj = {}
        self.skip_ws()
        if self.peek() == '}':
            self.advance()
            return obj
        while True:
            self.skip_ws()
            if self.eof():
                raise JsonParseError(
                    self.line, self.col,
                    "syntax error while parsing object key - "
                    "unexpected end of input; expected string literal",
                )
            if self.peek() != '"':
                last = self._read_literal_token_for_key()
                raise JsonParseError(
                    self.line, max(1, self.col - len(last)),
                    f"syntax error while parsing object key - "
                    f"invalid literal; last read: '{last}'; "
                    f"expected string literal",
                )
            key = self.parse_string()
            self.skip_ws()
            if self.peek() != ':':
                raise JsonParseError(
                    self.line, self.col,
                    "syntax error while parsing object separator - "
                    "unexpected end of input; expected ':'"
                    if self.eof()
                    else f"syntax error while parsing object separator - "
                    f"unexpected '{self.peek()}'; expected ':'",
                )
            self.advance()  # ':'
            val = self.parse_value()
            obj[key] = val
            self.skip_ws()
            if self.peek() == ',':
                self.advance()
                continue
            if self.peek() == '}':
                self.advance()
                return obj
            if self.eof():
                raise JsonParseError(
                    self.line, self.col,
                    "syntax error while parsing object - "
                    "unexpected end of input; expected '}'",
                )
            raise JsonParseError(
                self.line, self.col,
                f"syntax error while parsing object - "
                f"unexpected '{self.peek()}'; expected ',' or '}}'",
            )

    def _read_literal_token_for_key(self):
        start_pos = self.pos
        # include '{' or whatever unexpected char
        if not self.eof():
            first = self.peek()
            self.advance()
            # read next chars if they are letters
            while not self.eof() and self.peek().isalpha():
                self.advance()
                if self.pos - start_pos >= 8:
                    break
            return self.text[start_pos:self.pos]
        return ""

    def parse_array(self):
        self.advance()  # '['
        arr = []
        self.skip_ws()
        if self.peek() == ']':
            self.advance()
            return arr
        while True:
            val = self.parse_value()
            arr.append(val)
            self.skip_ws()
            if self.peek() == ',':
                self.advance()
                continue
            if self.peek() == ']':
                self.advance()
                return arr
            if self.eof():
                raise JsonParseError(
                    self.line, self.col,
                    "syntax error while parsing array - "
                    "unexpected end of input; expected ']'",
                )
            raise JsonParseError(
                self.line, self.col,
                f"syntax error while parsing array - "
                f"unexpected '{self.peek()}'; expected ',' or ']'",
            )

    def parse_string(self):
        self.advance()  # opening quote
        out = []
        while True:
            if self.eof():
                raise JsonParseError(
                    self.line, self.col,
                    "syntax error while parsing value - "
                    "unexpected end of input; expected '\"'",
                )
            ch = self.advance()
            if ch == '"':
                return "".join(out)
            if ch == '\\':
                if self.eof():
                    raise JsonParseError(
                        self.line, self.col,
                        "syntax error while parsing value - "
                        "unexpected end of input in string escape",
                    )
                esc = self.advance()
                mapping = {
                    '"': '"', '\\': '\\', '/': '/',
                    'b': '\b', 'f': '\f', 'n': '\n', 'r': '\r', 't': '\t',
                }
                if esc in mapping:
                    out.append(mapping[esc])
                elif esc == 'u':
                    hex4 = self.text[self.pos:self.pos + 4]
                    if len(hex4) < 4:
                        raise JsonParseError(
                            self.line, self.col,
                            "syntax error while parsing value - "
                            "bad unicode escape",
                        )
                    for _ in range(4):
                        self.advance()
                    try:
                        out.append(chr(int(hex4, 16)))
                    except ValueError:
                        raise JsonParseError(
                            self.line, self.col,
                            f"syntax error while parsing value - "
                            f"invalid unicode escape: \\u{hex4}",
                        )
                else:
                    raise JsonParseError(
                        self.line, self.col,
                        f"syntax error while parsing value - "
                        f"invalid escape: \\{esc}",
                    )
            else:
                out.append(ch)

    def parse_number(self):
        start = self.pos
        if self.peek() == '-':
            self.advance()
        while not self.eof() and (self.peek().isdigit() or self.peek() in ".eE+-"):
            self.advance()
        literal = self.text[start:self.pos]
        try:
            if any(c in literal for c in ".eE"):
                return float(literal)
            return int(literal)
        except ValueError:
            raise JsonParseError(
                self.line, self.col,
                f"syntax error while parsing value - "
                f"invalid number: '{literal}'",
            )

    def parse_keyword(self):
        for word, value in (("true", True), ("false", False), ("null", None)):
            if self.text.startswith(word, self.pos):
                for _ in word:
                    self.advance()
                return value
        # invalid literal
        start = self.pos
        while not self.eof() and self.peek().isalpha():
            self.advance()
            if self.pos - start >= 8:
                break
        last = self.text[start:self.pos]
        raise JsonParseError(
            self.line, self.col - len(last),
            f"syntax error while parsing value - "
            f"invalid literal; last read: '{last}'",
        )


def parse_json(text: str):
    return JsonParser(text).parse()


# ----- TUI rendering -----

COLOR_KEY = "\x1b[94m"
COLOR_STRING = "\x1b[92m"
COLOR_NUMBER = "\x1b[96m"
COLOR_BOOL = "\x1b[93m"
COLOR_NULL = "\x1b[91m"
COLOR_DIM = "\x1b[90m"
RESET_FG = "\x1b[39m"
RESET_BG = "\x1b[49m"
RESET = "\x1b[0m"
REVERSE = "\x1b[7m"
BOLD = "\x1b[1m"


def json_escape_string(s):
    out = ['"']
    for ch in s:
        if ch == '"':
            out.append('\\"')
        elif ch == '\\':
            out.append('\\\\')
        elif ch == '\n':
            out.append('\\n')
        elif ch == '\r':
            out.append('\\r')
        elif ch == '\t':
            out.append('\\t')
        elif ord(ch) < 0x20:
            out.append(f'\\u{ord(ch):04x}')
        else:
            out.append(ch)
    out.append('"')
    return "".join(out)


def render_primitive(value):
    if value is None:
        return COLOR_NULL + "null" + RESET_FG
    if isinstance(value, bool):
        return COLOR_BOOL + ("true" if value else "false") + RESET_FG
    if isinstance(value, (int, float)):
        if isinstance(value, float) and value.is_integer():
            # preserve dot
            return COLOR_NUMBER + f"{value}" + RESET_FG
        return COLOR_NUMBER + str(value) + RESET_FG
    if isinstance(value, str):
        return COLOR_STRING + json_escape_string(value) + RESET_FG
    return str(value)


def render_json(value, indent=0, is_root=True):
    """Render JSON with expanded tree view (default rendering)."""
    sp = "  " * indent
    lines = []
    if isinstance(value, dict):
        if not value:
            lines.append(sp + "{}")
            return lines
        if is_root:
            lines.append(REVERSE + "{" + RESET + RESET_FG + RESET_BG)
        else:
            lines.append("{")
        sorted_keys = sorted(value.keys())
        for i, k in enumerate(sorted_keys):
            v = value[k]
            last = (i == len(sorted_keys) - 1)
            key_repr = COLOR_KEY + json_escape_string(k) + RESET_FG
            if isinstance(v, dict):
                if not v:
                    lines.append("  " * (indent + 1) + key_repr + ": {}" + ("" if last else ","))
                else:
                    sub = render_json(v, indent + 1, is_root=False)
                    # first line is '{'
                    lines.append("  " * (indent + 1) + key_repr + ": " + BOLD + sub[0] + RESET + RESET_FG + RESET_BG)
                    lines.extend(sub[1:-1])
                    lines.append(sub[-1] + ("" if last else ","))
            elif isinstance(v, list):
                if not v:
                    lines.append("  " * (indent + 1) + key_repr + ": []" + ("" if last else ","))
                else:
                    # collapsed by default - show [...] with optional (table view)
                    table_hint = ""
                    if all(isinstance(e, dict) for e in v):
                        table_hint = "   " + COLOR_DIM + "(table view)" + RESET_FG
                    lines.append(
                        "  " * (indent + 1) + key_repr + ": " +
                        BOLD + "[...]" + ("" if last else ",") + RESET + RESET_FG + RESET_BG +
                        table_hint
                    )
            else:
                lines.append("  " * (indent + 1) + key_repr + ": " + render_primitive(v) + ("" if last else ","))
        lines.append(sp + "}")
        return lines
    if isinstance(value, list):
        if not value:
            lines.append(sp + "[]")
            return lines
        if is_root:
            lines.append(REVERSE + "[" + RESET + RESET_FG + RESET_BG)
        else:
            lines.append("[")
        for i, v in enumerate(value):
            last = (i == len(value) - 1)
            if isinstance(v, (dict, list)):
                sub = render_json(v, indent + 1, is_root=False)
                lines.append("  " * (indent + 1) + BOLD + sub[0] + RESET + RESET_FG + RESET_BG)
                lines.extend(sub[1:-1])
                lines.append(sub[-1] + ("" if last else ","))
            else:
                lines.append("  " * (indent + 1) + render_primitive(v) + ("" if last else ","))
        lines.append(sp + "]")
        return lines
    # primitive at root
    if is_root:
        return [REVERSE + str(value) + RESET + RESET_FG + RESET_BG]
    return [render_primitive(value)]


def run_tui(value):
    """Very small static TUI: print rendering then read one key from /dev/tty to exit."""
    # Open /dev/tty for input so stdin (if consumed) doesn't interfere.
    lines = render_json(value)
    sys.stdout.write("\n".join(lines) + "\n")
    sys.stdout.flush()
    # Read keystrokes until q or ESC
    try:
        tty = open("/dev/tty", "rb", buffering=0)
    except OSError:
        return
    import termios
    import tty as ttymod
    fd = tty.fileno()
    try:
        old = termios.tcgetattr(fd)
    except termios.error:
        tty.close()
        return
    try:
        ttymod.setraw(fd)
        while True:
            ch = tty.read(1)
            if not ch:
                break
            if ch in (b"q", b"\x1b", b"\x03", b"\x04"):
                break
    finally:
        termios.tcsetattr(fd, termios.TCSADRAIN, old)
        tty.close()


def read_input(path):
    """Read JSON input from file or stdin.

    Returns (text, err_msg). On failure text is None.
    """
    if path is not None:
        try:
            with open(path, "rb") as f:
                data = f.read()
        except OSError:
            return None, f"Could not open file {path}"
        try:
            return data.decode("utf-8", errors="replace"), None
        except Exception as e:
            return None, str(e)
    # stdin
    sys.stdout.write("Reading from stdin...")
    sys.stdout.flush()
    data = sys.stdin.buffer.read()
    return data.decode("utf-8", errors="replace"), None


def main(argv):
    opts = parse_args(argv)
    if opts["error"]:
        sys.stderr.write(opts["error"] + "\n")
        return 1
    if opts["help"]:
        sys.stdout.write(HELP_TEXT)
        return 0
    if opts["version"]:
        sys.stdout.write(VERSION_TEXT)
        return 0
    if opts["keybinding"]:
        sys.stdout.buffer.write(build_keybinding())
        sys.stdout.flush()
        return 0
    text, err = read_input(opts["file"])
    if err:
        sys.stderr.write(err + "\n")
        return 1
    try:
        value = parse_json(text)
    except JsonParseError as e:
        sys.stderr.write("\n" + str(e) + "\n")
        return 1
    run_tui(value)
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main(sys.argv[1:]))
    except BrokenPipeError:
        sys.exit(0)
