def build_keybinding() -> bytes:
    """Build the byte sequence for --keybinding output."""
    W1, W2 = 11, 16
    NL = b"\r\n"

    def pad(text: str, w: int) -> str:
        return text + " " * (w - len(text))

    top = "┌" + "─" * W1 + "┬" + "─" * W2 + "┐"
    sep = "├" + "─" * W1 + "┼" + "─" * W2 + "┤"
