# JSON parser (produces nlohmann/json-style error messages)

class JsonParseError(Exception):
    def __init__(self, line, column, message):
        self.line = line
        self.column = column
        self.message = message
        super().__init__(message)

    def __str__(self):
        return (
            f"[json.exception.parse_error.101] parse error at line "
            f"{self.line}, column {self.column}: {self.message}"
        )


class JsonParser:
    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.line = 1
        self.col = 1

    def eof(self):
        return self.pos >= len(self.text)

    def peek(self):
        return self.text[self.pos] if self.pos < len(self.text) else ""

    def advance(self):
        ch = self.text[self.pos]
        self.pos += 1
        if ch == "\n":
            self.line += 1
            self.col = 1
        else:
            self.col += 1
        return ch

    def skip_ws(self):
        while not self.eof() and self.peek() in " \t\n\r":
            self.advance()

    def parse(self):
        self.skip_ws()
        if self.eof():
            raise JsonParseError(
                self.line, self.col,
                "attempting to parse an empty input; "
                "check that your input string or stream contains the expected JSON",
            )
        value = self.parse_value()
        # trailing whitespace is fine; extra non-whitespace is an error
        self.skip_ws()
        if not self.eof():
            raise JsonParseError(
                self.line, self.col,
                f"syntax error while parsing value - "
                f"unexpected '{self.peek()}'; expected end of input",
            )
        return value

    def parse_value(self, context="value"):
        self.skip_ws()
        if self.eof():
            raise JsonParseError(
                self.line, self.col,
                f"syntax error while parsing {context} - "
                f"unexpected end of input; expected '[', '{{', or a literal",
            )
        ch = self.peek()
        if ch == "{":
            return self.parse_object()
        if ch == "[":
            return self.parse_array()
        if ch == '"':
            return self.parse_string()
        if ch == "-" or ch.isdigit():
            return self.parse_number()
        if ch in "tfn":
            return self.parse_keyword(context)
        # generic invalid literal
        self.advance()
        raise JsonParseError(
            self.line, max(1, self.col - 1),
            f"syntax error while parsing {context} - "
            f"invalid literal; last read: '{ch}'",
        )

    def parse_keyword(self, context="value"):
        start_pos = self.pos
        first = self.peek()
        expected = {"t": "true", "f": "false", "n": "null"}[first]
        value = {"true": True, "false": False, "null": None}[expected]
        for c in expected:
            if not self.eof() and self.peek() == c:
                self.advance()
            else:
                break
        matched = self.text[start_pos:self.pos]
        if matched == expected:
            return value
        raise JsonParseError(
            self.line, max(1, self.col - 1),
            f"syntax error while parsing {context} - "
            f"invalid literal; last read: '{matched}'",
        )

    def parse_object(self):
        self.advance()  # '{'
        obj = {}
        self.skip_ws()
        if self.peek() == "}":
            self.advance()
            return obj
        while True:
            self.skip_ws()
            if self.peek() != '"':
                # include the opening '{' and one lookahead char in "last read"
                read = "{" + self.peek()
                if not self.eof():
                    self.advance()
                raise JsonParseError(
                    self.line, max(1, self.col - 1),
                    f"syntax error while parsing object key - "
                    f"invalid literal; last read: '{read}'; "
                    f"expected string literal",
                )
            key = self.parse_string()
            self.skip_ws()
            if self.peek() != ":":
                raise JsonParseError(
                    self.line, self.col,
                    f"syntax error while parsing object separator - "
                    f"unexpected end of input; expected ':'"
                    if self.eof()
                    else f"syntax error while parsing object separator - "
                    f"unexpected '{self.peek()}'; expected ':'",
                )
            self.advance()  # ':'
            value = self.parse_value()
            obj[key] = value
            self.skip_ws()
            if self.peek() == ",":
                self.advance()
                continue
            if self.peek() == "}":
                self.advance()
                return obj
            if self.eof():
                raise JsonParseError(
                    self.line, self.col,
                    "syntax error while parsing object - "
                    "unexpected end of input; expected '}'",
                )
            raise JsonParseError(
                self.line, self.col,
                f"syntax error while parsing object - "
                f"unexpected '{self.peek()}'; expected ',' or '}}'",
            )

    def parse_array(self):
        self.advance()  # '['
        arr = []
        self.skip_ws()
        if self.peek() == "]":
            self.advance()
            return arr
        while True:
            value = self.parse_value()
            arr.append(value)
            self.skip_ws()
            if self.peek() == ",":
                self.advance()
                continue
            if self.peek() == "]":
                self.advance()
                return arr
            if self.eof():
                raise JsonParseError(
                    self.line, self.col,
                    "syntax error while parsing value - "
                    "unexpected end of input; expected '[', '{', or a literal",
                )
            raise JsonParseError(
                self.line, self.col,
                f"syntax error while parsing array - "
                f"unexpected '{self.peek()}'; expected ',' or ']'",
            )

    def parse_string(self):
        self.advance()  # opening quote
        out = []
        while True:
            if self.eof():
                raise JsonParseError(
                    self.line, self.col,
                    "syntax error while parsing value - "
                    "unexpected end of input; expected '\"'",
                )
