        "version": False,
        "keybinding": False,
        "fullscreen": False,
        "file": None,
        "error": None,
    }
    positional = []
    after_dashdash = False
    for a in argv:
        if after_dashdash:
            positional.append(a)
            continue
        if a == "--":
            after_dashdash = True
            continue
        if a.startswith("--"):
            name = a[2:]
            if name == "help":
                state["help"] = True
            elif name == "version":
                state["version"] = True
            elif name in ("key", "keybinding"):
                state["keybinding"] = True
            elif name == "fullscreen":
                state["fullscreen"] = True
            else:
                state["error"] = "Invalid arguments"
                return state
            continue
        if a.startswith("-") and len(a) >= 2:
            for ch in a[1:]:
                if ch == "h":
                    state["help"] = True
                elif ch == "v":
                    state["version"] = True
                elif ch == "k":
                    state["keybinding"] = True
                elif ch == "f":
                    state["fullscreen"] = True
                else:
                    state["error"] = "Invalid arguments"
                    return state
            continue
        positional.append(a)

    if len(positional) > 1:
        state["error"] = "Invalid arguments"
        return state
    if positional:
        state["file"] = positional[0]
    return state


