# JSON parser (produces nlohmann/json-style error messages)

class JsonParseError(Exception):
    def __init__(self, line, column, message):
        self.line = line
        self.column = column
        self.message = message
        super().__init__(message)

    def __str__(self):
        return (
            f"[json.exception.parse_error.101] parse error at line "
            f"{self.line}, column {self.column}: {self.message}"
        )


class JsonParser:
    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.line = 1
        self.col = 1

    def eof(self):
        return self.pos >= len(self.text)

    def peek(self):
        return self.text[self.pos] if self.pos < len(self.text) else ""

    def advance(self):
        ch = self.text[self.pos]
        self.pos += 1
        if ch == "\n":
            self.line += 1
            self.col = 1
        else:
            self.col += 1
        return ch

    def skip_ws(self):
        while not self.eof() and self.peek() in " \t\n\r":
            self.advance()

    def parse(self):
        self.skip_ws()
        if self.eof():
            raise JsonParseError(
                self.line, self.col,
                "attempting to parse an empty input; "
                "check that your input string or stream contains the expected JSON",
            )
        value = self.parse_value()
        # trailing whitespace is fine; extra non-whitespace is an error
        self.skip_ws()
        if not self.eof():
            raise JsonParseError(
                self.line, self.col,
                f"syntax error while parsing value - "
                f"unexpected '{self.peek()}'; expected end of input",
            )
        return value

    def parse_value(self, context="value"):
        self.skip_ws()
        if self.eof():
            raise JsonParseError(
                self.line, self.col,
                f"syntax error while parsing {context} - "
                f"unexpected end of input; expected '[', '{{', or a literal",
            )
        ch = self.peek()
        if ch == "{":
            return self.parse_object()
        if ch == "[":
            return self.parse_array()
        if ch == '"':
            return self.parse_string()
        if ch == "-" or ch.isdigit():
            return self.parse_number()
        if ch in "tfn":
            return self.parse_keyword(context)
        # generic invalid literal
        self.advance()
        raise JsonParseError(
            self.line, max(1, self.col - 1),
            f"syntax error while parsing {context} - "
            f"invalid literal; last read: '{ch}'",
        )

    def parse_keyword(self, context="value"):
        start_pos = self.pos
        first = self.peek()
        expected = {"t": "true", "f": "false", "n": "null"}[first]
        value = {"true": True, "false": False, "null": None}[expected]
        for c in expected:
            if not self.eof() and self.peek() == c:
                self.advance()
            else:
                break
        matched = self.text[start_pos:self.pos]
        if matched == expected:
            return value
        raise JsonParseError(
            self.line, max(1, self.col - 1),
            f"syntax error while parsing {context} - "
            f"invalid literal; last read: '{matched}'",
        )

    def parse_object(self):
        self.advance()  # '{'
        obj = {}
        self.skip_ws()
        if self.peek() == "}":
            self.advance()
            return obj
        while True:
            self.skip_ws()
            if self.peek() != '"':
                # include the opening '{' and one lookahead char in "last read"
                read = "{" + self.peek()
                if not self.eof():
                    self.advance()
                raise JsonParseError(
                    self.line, max(1, self.col - 1),
                    f"syntax error while parsing object key - "
                    f"invalid literal; last read: '{read}'; "
                    f"expected string literal",
                )
            key = self.parse_string()
            self.skip_ws()
            if self.peek() != ":":
                raise JsonParseError(
                    self.line, self.col,
                    f"syntax error while parsing object separator - "
                    f"unexpected end of input; expected ':'"
                    if self.eof()
                    else f"syntax error while parsing object separator - "
                    f"unexpected '{self.peek()}'; expected ':'",
                )
            self.advance()  # ':'
            value = self.parse_value()
            obj[key] = value
            self.skip_ws()
            if self.peek() == ",":
                self.advance()
                continue
            if self.peek() == "}":
                self.advance()
                return obj
            if self.eof():
                raise JsonParseError(
                    self.line, self.col,
                    "syntax error while parsing object - "
                    "unexpected end of input; expected '}'",
                )
            raise JsonParseError(
                self.line, self.col,
                f"syntax error while parsing object - "
                f"unexpected '{self.peek()}'; expected ',' or '}}'",
            )

    def parse_array(self):
        self.advance()  # '['
        arr = []
        self.skip_ws()
        if self.peek() == "]":
            self.advance()
            return arr
        while True:
            value = self.parse_value()
            arr.append(value)
            self.skip_ws()
            if self.peek() == ",":
                self.advance()
                continue
            if self.peek() == "]":
                self.advance()
                return arr
            if self.eof():
                raise JsonParseError(
                    self.line, self.col,
                    "syntax error while parsing value - "
                    "unexpected end of input; expected '[', '{', or a literal",
                )
            raise JsonParseError(
                self.line, self.col,
                f"syntax error while parsing array - "
                f"unexpected '{self.peek()}'; expected ',' or ']'",
            )

    def parse_string(self):
        self.advance()  # opening quote
        out = []
        while True:
            if self.eof():
                raise JsonParseError(
                    self.line, self.col,
                    "syntax error while parsing value - "
                    "unexpected end of input; expected '\"'",
                )
            ch = self.advance()
            if ch == '"':
                return "".join(out)
            if ch == "\\":
                if self.eof():
                    raise JsonParseError(
                        self.line, self.col,
                        "syntax error while parsing value - "
                        "unexpected end of input in string escape",
                    )
                esc = self.advance()
                mapping = {
                    '"': '"', "\\": "\\", "/": "/",
                    "b": "\b", "f": "\f", "n": "\n", "r": "\r", "t": "\t",
                }
                if esc in mapping:
                    out.append(mapping[esc])
                elif esc == "u":
                    hex4 = self.text[self.pos:self.pos + 4]
                    if len(hex4) < 4:
                        raise JsonParseError(
                            self.line, self.col,
                            "syntax error while parsing value - "
                            "bad unicode escape",
                        )
                    for _ in range(4):
                        self.advance()
                    try:
                        out.append(chr(int(hex4, 16)))
                    except ValueError:
                        raise JsonParseError(
                            self.line, self.col,
                            f"syntax error while parsing value - "
                            f"invalid unicode escape: \\u{hex4}",
                        )
                else:
                    raise JsonParseError(
                        self.line, self.col,
                        f"syntax error while parsing value - "
                        f"invalid escape: \\{esc}",
                    )
            else:
                out.append(ch)

    def parse_number(self):
        start = self.pos
        if self.peek() == "-":
            self.advance()
        while not self.eof() and (self.peek().isdigit() or self.peek() in ".eE+-"):
            self.advance()
        literal = self.text[start:self.pos]
        try:
            if any(c in literal for c in ".eE"):
                return float(literal)
            return int(literal)
        except ValueError:
            raise JsonParseError(
                self.line, self.col,
                f"syntax error while parsing value - "
                f"invalid number: '{literal}'",
            )


def parse_json(text: str):
    return JsonParser(text).parse()


# ---------------------------------------------------------------------------
# Rendering

COLOR_KEY = "\x1b[94m"
COLOR_STRING = "\x1b[92m"
COLOR_NUMBER = "\x1b[96m"
COLOR_BOOL = "\x1b[93m"
COLOR_NULL = "\x1b[91m"
COLOR_DIM = "\x1b[90m"
RESET_FG = "\x1b[39m"
RESET_BG = "\x1b[49m"
RESET = "\x1b[0m"
REVERSE = "\x1b[7m"
BOLD = "\x1b[1m"


def json_escape_string(s):
    out = ['"']
    for ch in s:
        if ch == '"':
            out.append('\\"')
        elif ch == "\\":
            out.append("\\\\")
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\r":
            out.append("\\r")
        elif ch == "\t":
            out.append("\\t")
        elif ord(ch) < 0x20:
            out.append(f"\\u{ord(ch):04x}")
        else:
            out.append(ch)
    out.append('"')
    return "".join(out)


def render_number(value):
    if isinstance(value, bool):
        return COLOR_BOOL + ("true" if value else "false") + RESET_FG
    if isinstance(value, float):
        if value.is_integer():
            return COLOR_NUMBER + f"{value:.1f}" + RESET_FG
        return COLOR_NUMBER + repr(value) + RESET_FG
    return COLOR_NUMBER + str(value) + RESET_FG


def render_primitive(value):
    if value is None:
        return COLOR_NULL + "null" + RESET_FG
    if isinstance(value, bool):
        return COLOR_BOOL + ("true" if value else "false") + RESET_FG
    if isinstance(value, (int, float)):
        return render_number(value)
    if isinstance(value, str):
        return COLOR_STRING + json_escape_string(value) + RESET_FG
    return str(value)


def render_json(value, indent=0, is_root=True):
    pad = "  " * indent
    lines = []
    if isinstance(value, dict):
        if not value:
            lines.append(pad + "{}")
            return lines
        open_brace = (REVERSE + "{" + RESET + RESET_FG + RESET_BG) if is_root else "{"
        lines.append(open_brace)
        keys = sorted(value.keys())
        for i, k in enumerate(keys):
            v = value[k]
            last = i == len(keys) - 1
            key_text = COLOR_KEY + json_escape_string(k) + RESET_FG
            inner_pad = "  " * (indent + 1)
            if isinstance(v, dict):
                if not v:
                    lines.append(inner_pad + key_text + ": {}" + ("" if last else ","))
                else:
                    sub = render_json(v, indent + 1, is_root=False)
                    lines.append(
                        inner_pad + key_text + ": " + BOLD + sub[0] + RESET + RESET_FG + RESET_BG
                    )
                    lines.extend(sub[1:-1])
                    lines.append(sub[-1] + ("" if last else ","))
            elif isinstance(v, list):
                if not v:
                    lines.append(inner_pad + key_text + ": []" + ("" if last else ","))
                else:
                    table_hint = ""
                    if all(isinstance(e, dict) for e in v):
                        table_hint = "   " + COLOR_DIM + "(table view)" + RESET_FG
                    lines.append(
                        inner_pad + key_text + ": "
                        + BOLD + "[...]" + ("" if last else ",")
                        + RESET + RESET_FG + RESET_BG + table_hint
                    )
            else:
                lines.append(
                    inner_pad + key_text + ": " + render_primitive(v) + ("" if last else ",")
                )
        lines.append(pad + "}")
        return lines
    if isinstance(value, list):
        if not value:
            lines.append(pad + "[]")
            return lines
        open_bracket = (REVERSE + "[" + RESET + RESET_FG + RESET_BG) if is_root else "["
        lines.append(open_bracket)
        for i, v in enumerate(value):
            last = i == len(value) - 1
            inner_pad = "  " * (indent + 1)
            if isinstance(v, (dict, list)):
                sub = render_json(v, indent + 1, is_root=False)
                lines.append(inner_pad + BOLD + sub[0] + RESET + RESET_FG + RESET_BG)
                lines.extend(sub[1:-1])
                lines.append(sub[-1] + ("" if last else ","))
            else:
                lines.append(inner_pad + render_primitive(v) + ("" if last else ","))
        lines.append(pad + "]")
        return lines
    # primitive at root
    if is_root:
        return [REVERSE + str(value) + RESET + RESET_FG + RESET_BG]
    return [render_primitive(value)]


def run_tui(value):
    """Render the JSON and wait for a quit keystroke on the terminal."""
    lines = render_json(value)
    sys.stdout.write("\n".join(lines) + "\n")
    sys.stdout.flush()
    # Block on /dev/tty for user input if available. Exit on q/ESC/ctrl-c/ctrl-d.
    try:
        tty = open("/dev/tty", "rb", buffering=0)
    except OSError:
        return
    import termios
    import tty as ttymod
    fd = tty.fileno()
    try:
        old = termios.tcgetattr(fd)
    except termios.error:
        tty.close()
        return
    try:
        ttymod.setraw(fd)
        while True:
            ch = tty.read(1)
            if not ch:
                break
            if ch in (b"q", b"\x1b", b"\x03", b"\x04"):
                break
    finally:
        termios.tcsetattr(fd, termios.TCSADRAIN, old)
        tty.close()


# ---------------------------------------------------------------------------
# Input

def read_input(path):
    if path is not None:
        try:
            with open(path, "rb") as f:
                data = f.read()
        except OSError:
            return None, f"Could not open file {path}"
        return data.decode("utf-8", errors="replace"), None
    sys.stdout.write("Reading from stdin...")
    sys.stdout.flush()
    data = sys.stdin.buffer.read()
    return data.decode("utf-8", errors="replace"), None


# ---------------------------------------------------------------------------
# Entry point

def main(argv):
    opts = parse_args(argv)
    if opts["error"]:
        sys.stderr.write(opts["error"] + "\n")
        return 1
    if opts["help"]:
        sys.stdout.write(HELP_TEXT)
        return 0
    if opts["version"]:
        sys.stdout.write(VERSION_TEXT)
        return 0
    if opts["keybinding"]:
        sys.stdout.buffer.write(build_keybinding())
        sys.stdout.flush()
        return 0
    text, err = read_input(opts["file"])
    if err:
        sys.stderr.write(err + "\n")
        return 1
    try:
        value = parse_json(text)
    except JsonParseError as e:
        sys.stderr.write("\n" + str(e) + "\n")
        return 1
    run_tui(value)
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main(sys.argv[1:]))
    except BrokenPipeError:
        sys.exit(0)
